def digits_base(n, base):
    """Get digits of n in the given base"""
    if n == 0:
        return []
    digits = []
    while n > 0:
        digits.append(n % base)
        n //= base
    return digits

def in_set_A(n):
    """Check if n is in setA (base-3 digits all 0 or 1)"""
    for d in digits_base(n, 3):
        if d > 1:
            return False
    return True

def in_set_B(n):
    """Check if n is in setB (base-4 digits all 0 or 1)"""
    for d in digits_base(n, 4):
        if d > 1:
            return False
    return True

def in_set_AB(n):
    """Check if n is in setAB"""
    for a in range(n + 1):
        if in_set_A(a):
            b = n - a
            if in_set_B(b):
                return True
    return False

# Find all numbers up to 200 that are NOT in setAB
not_in_AB = []
for n in range(200):
    if not in_set_AB(n):
        not_in_AB.append(n)

print("Numbers NOT in setAB (up to 200):")
print(not_in_AB)

# Print the first one
if not_in_AB:
    print(f"\nFirst number not in setAB: {not_in_AB[0]}")

    # Verify it
    n = not_in_AB[0]
    print(f"\nVerification for n = {n}:")
    print(f"  Decompositions of {n}:")
    for a in range(n + 1):
        if in_set_A(a):
            b = n - a
            print(f"    a = {a} ∈ setA, b = {b}, b ∈ setB? {in_set_B(b)}")
EOF

